from django.db import migrations, models


def fusion_to_cad_project(apps, schema_editor):
    """Rename the FUSION asset type to CAD_PROJECT (issue #140), and record Fusion as the CAD
    tool of every design that had one - FUSION only ever held Fusion project files."""
    Design = apps.get_model("device", "Design")
    DesignAsset = apps.get_model("device", "DesignAsset")
    fusion_assets = DesignAsset.objects.filter(asset_type="FUSION")
    Design.objects.filter(pk__in=fusion_assets.values("design_id")).update(cad_tool="FUSION")
    fusion_assets.update(asset_type="CAD_PROJECT")


def cad_project_to_fusion(apps, schema_editor):
    DesignAsset = apps.get_model("device", "DesignAsset")
    DesignAsset.objects.filter(asset_type="CAD_PROJECT").update(asset_type="FUSION")


